window.PHASES=[{"n":"Phase 0 — The first hour","lv":"Level 1–10","note":"Everything here happens on or next to the Moosewood dock."},{"n":"Phase 1 — Getting off the starter island","lv":"Level 10–40","note":"One shop rod, one free rod, one permanent unlock."},{"n":"Phase 2 — Income and enchants","lv":"Level 40–80","note":"Stop fishing wherever you happen to be and start farming on purpose."},{"n":"Phase 3 — The mid-game rod","lv":"Level 80–150","note":"The Trident Rod is the point of this phase; the Destiny Rod is the bonus."},{"n":"Phase 4 — Vertigo and The Depths","lv":"Level 150–180","note":"The hardest gate in the base game, and the one with no shortcut."},{"n":"Phase 5 — Atlantis","lv":"Level 180+","note":"The first content gated on your level rather than your wallet."},{"n":"Phase 6 — Endgame gear","lv":"Endgame","note":"Rods stop being upgrades and start being choices."},{"n":"Phase 7 — The money meta","lv":"Endgame","note":"Where the account stops progressing and starts printing."}];
