window.MILESTONES=[{id:"m-boat",ph:0,t:"Buy the Rowboat",cost:400,lvl:0,where:"Shipwright, Moosewood docks",body:"<b>400 C$</b> to the Shipwright. Until you own a boat, Fisch is one island; after it, island names reveal themselves as you sail near them and every location in this wiki becomes reachable.",done:s => s.f.boat},
{id:"m-carbon",ph:0,t:"Buy the Carbon Rod",cost:2000,lvl:0,where:"Marc&#8217;s shop, Moosewood",body:"Fish the Moosewood dock with the Flimsy Rod until you have <b>2,000 C$</b> and buy the <a href=\"{{B}}rods/carbon-rod/\">Carbon Rod</a>. Do not buy the Plastic or Training rods on the way &mdash; that is 900 C$ you then have to earn again.",done:s => s.ord >= ordOf("carbon-rod")},
{id:"m-easybest",ph:0,t:"Clear the four easy bestiary blocks",cost:0,lvl:0,where:"Moosewood, Roslit Bay, Terrapin, the Ocean",body:"Fill the <a href=\"{{B}}mechanics/bestiary/\">bestiary</a> for Moosewood, Roslit Bay, Terrapin Island and the Ocean. These four are the largest, easiest blocks in the game and they are what carries you toward the <b>70%</b> total that unlocks the Destiny Rod later. Doing them now costs nothing you were not already doing.",done:s => s.f.easybest},
{id:"m-steady",ph:1,t:"Buy the Steady Rod",cost:7000,lvl:0,where:"Blacksmith, Roslit Bay",body:"The <a href=\"{{B}}rods/steady-rod/\">Steady Rod</a> widens the shake window and adds enough resilience that you stop losing fish to the minigame. This is the rod that ends the early game.",done:s => s.ord >= ordOf("steady-rod")},
{id:"m-altar",ph:1,t:"Open the Keepers Altar",cost:400,lvl:0,where:"Mines, Statue of Sovereignty",body:"Sail to the <a href=\"{{B}}locations/statue-of-sovereignty/\">Statue of Sovereignty</a>, go into the mines, and pay the NPC by the elevator <b>400 C$</b>. That is the entire cost of permanently unlocking <a href=\"{{B}}guides/enchanting/\">enchanting</a>. There is no reason to still have this closed at level 200.",done:s => s.f.altar},
{id:"m-fungal",ph:1,t:"Take Agaric&#8217;s free Fungal Rod",cost:0,lvl:0,where:"Mushgrove Swamp",body:"Sail to <a href=\"{{B}}locations/mushgrove-swamp/\">Mushgrove Swamp</a>, talk to <a href=\"{{B}}npcs/agaric/\">Agaric</a>, catch one <b>Alligator</b>, and he hands over the <a href=\"{{B}}rods/fungal-rod/\">Fungal Rod</a> for free. Its luck passive beats anything you could buy at this point, and it costs nothing.",done:s => s.ord >= ordOf("fungal-rod")},
{id:"m-relics",ph:2,t:"Farm relics and enchant your rod",cost:0,lvl:0,where:"Ancient Isle, or the Roslit Bay shallows",body:"Fish <a href=\"{{B}}items/enchant-relic/\">Enchant Relics</a> in bulk &mdash; <a href=\"{{B}}locations/ancient-isle/\">Ancient Isle</a> if you can reach it, the Nurse Shark shallows in <a href=\"{{B}}locations/roslit-bay/\">Roslit Bay</a> if you cannot &mdash; then spend the whole stack at the altar in one sitting. Each roll <b>overwrites</b> the last, so stop the moment you land something worth keeping.",done:s => s.f.enchanted},
{id:"m-money1",ph:2,t:"Set up a real money farm",cost:0,lvl:0,where:"Forsaken Shores &mdash; the waterfall pond",body:"<a href=\"{{B}}locations/forsaken-shores/\">Forsaken Shores</a> is the mid-game answer to both money and XP, which is unusual &mdash; normally those are different places. Fish the waterfall pond, not the open shore. This is where the 150,000 C$ for the Trident Rod comes from.",done:s => s.ord >= ordOf("trident-rod") || s.cash >= 150000},
{id:"m-trident",ph:3,t:"Buy the Trident Rod",cost:150000,lvl:0,where:"Trident&#8217;s Temple",body:"The <a href=\"{{B}}rods/trident-rod/\">Trident Rod</a> is the correct target for any mid-game player who does not know what to save for. Its ~30% <a href=\"{{B}}mutations/atlantean/\">Atlantean</a> passive multiplies catch value by 3, so it earns a good share of its own price back.",done:s => s.ord >= ordOf("trident-rod")},
{id:"m-best70",ph:3,t:"Reach 70% bestiary &rarr; Destiny Rod",cost:190000,lvl:0,where:"Caleia, The Arch",body:"At <b>70% total bestiary</b>, <a href=\"{{B}}npcs/caleia/\">Caleia</a> at <a href=\"{{B}}locations/the-arch/\">The Arch</a> sells the <a href=\"{{B}}rods/destiny-rod/\">Destiny Rod</a> for 190,000 C$ &mdash; cheap for its tier. Finish whole easy locations to get there; percentage is percentage.",done:s => s.f.best70 || s.ord >= ordOf("destiny-rod")},
{id:"m-vertigo",ph:4,t:"Complete the Vertigo bestiary to 100%",cost:0,lvl:0,where:"Vertigo",body:"A hard gate with no shortcut. <a href=\"{{B}}locations/vertigo/\">Vertigo</a> must be at <b>100%</b> before The Depths Key can drop at all. Treat it as its own project rather than something that happens by accident.",done:s => s.f.vertigo},
{id:"m-depthskey",ph:4,t:"Fish The Depths Key from the Strange Whirlpool",cost:0,lvl:0,where:"Vertigo &mdash; the Strange Whirlpool",body:"With Vertigo at 100%, fish the <b>Strange Whirlpool</b> until you catch <a href=\"{{B}}items/depths-key/\">The Depths Key</a>. It cannot be bought or traded around.",done:s => s.f.depths},
{id:"m-depthsrod",ph:4,t:"Buy the Rod of the Depths",cost:750000,lvl:0,where:"Inside The Depths",body:"<b>750,000 C$</b> for the <a href=\"{{B}}rods/rod-of-the-depths/\">Rod of the Depths</a>. Bank the money <em>before</em> you go down &mdash; nothing in The Depths helps you earn it and the trip back out is long.",done:s => s.ord >= ordOf("rod-of-the-depths")},
{id:"m-level180",ph:5,t:"Reach level 180 for Atlantis",cost:0,lvl:180,where:"Wherever your XP stack is best",body:"<a href=\"{{B}}locations/atlantis/\">Atlantis</a> gates on character level as well as money &mdash; around <b>180</b>. If your level is short, money will not substitute; go stack XP bonuses and level deliberately (see <a href=\"{{B}}guides/xp-guide/\">XP &amp; levelling</a>).",done:s => s.lvl >= 180},
{id:"m-kraken",ph:5,t:"Atlantis: five levers, then the Kraken Rod",cost:1333333,lvl:0,where:"Atlantis",body:"Flick the five hidden levers &mdash; behind the Merchant, under the Cannon Hut, behind the Waterfall, on the Mountain Bridge, inside the Skull Cave &mdash; to open the Kraken Pool, and buy the <a href=\"{{B}}rods/kraken-rod/\">Kraken Rod</a> on the same trip. Budget the higher of the two published prices.",done:s => s.ord >= ordOf("kraken-rod")},
{id:"m-dreamer",ph:6,t:"Buy the Great Dreamer Rod",cost:500000,lvl:0,where:"Cursed Isle",body:"<b>500,000 C$</b> at <a href=\"{{B}}locations/cursed-isle/\">Cursed Isle</a> for high lure speed, high luck and a duplication passive. Cheaper than the Rod of the Depths and arguably stronger &mdash; if you can reach Cursed Isle, this is the better buy.",done:s => s.ord >= ordOf("great-dreamer-rod")},
{id:"m-exalted",ph:6,t:"Land an exalted enchant",cost:0,lvl:0,where:"Keepers Altar",body:"<a href=\"{{B}}items/exalted-relic/\">Exalted Relics</a> roll from a small pool of much stronger enchants: <a href=\"{{B}}enchants/quantum/\">Quantum</a> (25% Subspace mutations), <a href=\"{{B}}enchants/sea-overlord/\">Sea Overlord</a> (+25% weight, so +25% money forever) and <a href=\"{{B}}enchants/invincible/\">Invincible</a> (fish the hazard pools with any rod). Spend them on the rod you intend to keep.",done:s => s.f.exalted},
{id:"m-venue",ph:7,t:"Finish the ladder: Wingripper or Chrysalis",cost:0,lvl:0,where:"Underground Music Venue",body:"The <a href=\"{{B}}locations/underground-music-venue/\">Underground Music Venue</a> holds the two rods that mainstream progression guides finish on. Owning one makes the other a sidegrade &mdash; put the effort into enchanting instead.",done:s => s.ord >= ordOf("wingripper-rod")},
{id:"m-moneymeta",ph:7,t:"Move to the endgame money meta",cost:0,lvl:0,where:"Castaway Cliffs, or the Calm Zone",body:"Two farms: <a href=\"{{B}}locations/castaway-cliffs/\">Castaway Cliffs</a> with the <a href=\"{{B}}rods/elder-moss-ripper/\">Elder Moss Ripper</a> (15&ndash;25M C$/hr, because its Mossjaw passive is a two-minute timer rather than a luck roll), or the <a href=\"{{B}}locations/calm-zone/\">Calm Zone</a> for the Crystallized Seadragon at ~26,100 C$ average with whatever rod you already own.",done:s => s.f.moneymeta || s.ord >= ordOf("elder-moss-ripper")}];
